import ast
import operator

# 辞書で演算子を定義
OPERATORS = {
    ast.Expression: lambda args: args[0],
    ast.BinOp: lambda args, ops: {
        '+': operator.add, '-': operator.sub,
        '*': operator.mul, '/': operator.truediv,
        '//': operator.floordiv, '%': operator.mod, '**': operator.pow
    }[args[0].op.__name__] if hasattr(args[0].op, '__name__') else args[1],  # 乗算演算子のみサポート
    ast.UnaryOp: lambda args, ops: {
        '+': lambda x: x, '-': operator.neg,
    }[args[0].op.__name__](ast.literal_eval(ops[0]))
}

# 式を Python AST に変換し、評価する関数
def eval_expression(expr):
    try:
        tree = ast.parse(f'({expr})')
        code = compile(tree, '<string>', 'eval')
        return eval(code)
    except ZeroDivisionError as e:
        raise ZeroDivisionError("ゼロで割ることはできません。") from e
    except SyntaxError as e:
        raise SyntaxError("無効な数学式の形式です。") from e
    except RecursionError as e:
        raise RecursionError("式が深すぎます（再帰制限）。") from e
    except Exception as e:
        raise ValueError(f"計算エラーが発生しました：{e}") from e
